import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Avatar } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/separator";
import { ScrollArea } from "@/components/ui/scroll";

const appointments = {
  today: [
    {
      id: 1,
      patient: { name: "John Doe", avatar: null },
      time: "10:00 AM",
      date: "2024-06-10",
      type: "Video",
      status: "confirmed",
    },
    {
      id: 2,
      patient: { name: "Jane Smith", avatar: null },
      time: "2:00 PM",
      date: "2024-06-10",
      type: "In-person",
      status: "cancelled",
    },
  ],
  upcoming: [
    {
      id: 3,
      patient: { name: "Alice Brown", avatar: null },
      time: "11:00 AM",
      date: "2024-06-12",
      type: "Video",
      status: "confirmed",
    },
  ],
  past: [
    {
      id: 4,
      patient: { name: "Bob Lee", avatar: null },
      time: "9:00 AM",
      date: "2024-06-08",
      type: "In-person",
      status: "confirmed",
    },
  ],
};

function AppointmentCard({ appointment }) {
  return (
    <Card className="rounded-xl p-4 shadow flex flex-col gap-3 text-gray-700 hover:bg-gray-50 transition">
      <div className="flex items-center gap-3">
        <Avatar name={appointment.patient.name} src={appointment.patient.avatar} />
        <div className="font-semibold">{appointment.patient.name}</div>
        <Badge className="ml-auto">{appointment.time} | {appointment.date}</Badge>
      </div>
      <div className="flex items-center gap-2">
        <Badge variant="outline">{appointment.type}</Badge>
        <Badge variant={appointment.status === "confirmed" ? "default" : "destructive"}>
          {appointment.status.charAt(0).toUpperCase() + appointment.status.slice(1)}
        </Badge>
      </div>
      <Separator />
      <div className="flex gap-2">
        <Button size="sm" className="rounded-lg" disabled={appointment.status !== "confirmed"}>
          Start Consultation
        </Button>
        <Button size="sm" variant="outline" className="rounded-lg" disabled={appointment.status !== "confirmed"}>
          Cancel
        </Button>
      </div>
    </Card>
  );
}

export default function DoctorAppointmentsPage() {
  return (
    <div className="max-w-2xl mx-auto py-8">
      <h1 className="text-2xl font-bold mb-6">My Appointments</h1>
      <Tabs defaultValue="today" className="w-full">
        <TabsList className="mb-4">
          <TabsTrigger value="today">Today</TabsTrigger>
          <TabsTrigger value="upcoming">Upcoming</TabsTrigger>
          <TabsTrigger value="past">Past</TabsTrigger>
        </TabsList>
        <TabsContent value="today">
          <ScrollArea className="h-96 pr-2">
            <div className="flex flex-col gap-4">
              {appointments.today.length ? appointments.today.map((appt) => (
                <AppointmentCard key={appt.id} appointment={appt} />
              )) : <div className="text-center text-gray-400">No appointments for today.</div>}
            </div>
          </ScrollArea>
        </TabsContent>
        <TabsContent value="upcoming">
          <ScrollArea className="h-96 pr-2">
            <div className="flex flex-col gap-4">
              {appointments.upcoming.length ? appointments.upcoming.map((appt) => (
                <AppointmentCard key={appt.id} appointment={appt} />
              )) : <div className="text-center text-gray-400">No upcoming appointments.</div>}
            </div>
          </ScrollArea>
        </TabsContent>
        <TabsContent value="past">
          <ScrollArea className="h-96 pr-2">
            <div className="flex flex-col gap-4">
              {appointments.past.length ? appointments.past.map((appt) => (
                <AppointmentCard key={appt.id} appointment={appt} />
              )) : <div className="text-center text-gray-400">No past appointments.</div>}
            </div>
          </ScrollArea>
        </TabsContent>
      </Tabs>
    </div>
  );
} 